```
  let background = """
    

    |￣￣￣￣￣￣￣|
    |              |
    |＿＿＿＿＿_＿_|
    (\\__/) ||
    (•ㅅ•) ||
    / 　 づ
    """
  var body: some View {
    ZStack(alignment: .center) {
      Text("Broccoli ♡♡♡")
      VStack {
        ForEach(background.components(separatedBy: "\n"), id: \.self) { line in
          Text(line)
        }
      }
    }
  }
```

